def transform(grid):
 h=len(grid); w=len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   col=grid[r][c]; pts=[]; stack=[(r,c)]; seen.add((r,c))
   while stack:
    a,b=stack.pop(); pts.append((a,b))
    for x,y in [(a-1,b),(a+1,b),(a,b-1),(a,b+1)]:
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==col:
      seen.add((x,y)); stack.append((x,y))
   a=min(x for x,y in pts); b=max(x for x,y in pts); c0=min(y for x,y in pts); d=max(y for x,y in pts)
   if len(pts)==(b-a+1)*(d-c0+1): objs.append((len(pts),a,b,c0,d))
 if objs:
  _,a,b,c,d=max(objs)
  return [row[c:d+1] for row in grid[a:b+1]]
 return grid

